insert into public.faqs (
  id,
  question,
  keywords,
  category,
  answer,
  next_step,
  suggest_doctor,
  risk_level,
  is_active
)
values
  ('90000000-0000-4000-8000-000000000001', '健康云平台咋登录', array['健康云', '健康云平台', '怎么登录', '咋登录', '登录'], '平台使用', '第一次使用健康云时，通常需要先完成实名认证，再按页面提示登录。如果不会操作，可以请家属或社区工作人员协助。', '如果您是卡在某一步，可以把卡住的那一步说出来，我先帮您按流程整理。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000002', '我不会用健康云怎么办', array['不会用健康云', '健康云不会用', '不会操作', '老人不会用'], '平台使用', '如果不会使用健康云，可以先请家属、居委老师或社区工作人员协助。家医 Claw 可以先帮您梳理流程，但不能代替真实账号操作。', '也可以点击一键找人，联系家属、社区或家庭医生团队协助。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000003', '小程序不会用怎么预约体检', array['小程序', '预约体检', '不会用怎么预约', '体检预约'], '体检流程', '如果不会用小程序预约体检，可以先看社区通知，或请家属、社区工作人员协助操作。不同社区的预约方式可能不同。', '先确认本社区体检时间和入口，再联系社区卫生服务中心核实。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000004', '药没了咋办', array['药没了', '药吃完了', '没药了', '配药', '续方'], '配药用药', '慢病药快吃完时，建议提前联系家庭医生或社区卫生服务中心确认续方和配药安排，不要等完全断药后再处理。', '可以先准备药盒、旧处方或用药清单，再联系家庭医生团队。', true, 'medium', true),
  ('90000000-0000-4000-8000-000000000005', '开药怎么弄', array['开药', '配药', '拿药', '续药'], '配药用药', '是否能开药、在哪里开、能开多久，通常要看您当前病情、既往处方和当地规定。', '建议联系家庭医生团队确认续方和配药流程。', true, 'medium', true),
  ('90000000-0000-4000-8000-000000000006', '体检报告看不懂', array['体检报告', '看不懂', '报告怎么看', '体检结果'], '体检报告', '体检报告里的指标需要结合年龄、病史、近期症状和既往用药一起判断。家医 Claw 可以解释流程，但不能代替医生判断严重程度。', '建议带完整报告联系家庭医生团队进一步解读。', true, 'medium', true),
  ('90000000-0000-4000-8000-000000000007', '报告上有箭头怎么办', array['报告有箭头', '指标异常', '报告异常', '箭头怎么办'], '体检报告', '报告上有箭头不一定代表严重，但说明这个指标和参考范围不一致，需要结合完整情况判断。', '建议带完整报告联系家庭医生或线下医生确认是否需要复查或转诊。', true, 'medium', true),
  ('90000000-0000-4000-8000-000000000008', '怎么找李医生', array['找李医生', '联系医生', '怎么找医生', '家庭医生电话'], '联系医生', '您可以通过签约时留下的电话、社区卫生服务中心、微信群，或平台里的一键找人入口联系家庭医生团队。', '可以点击一键找人，先找到家庭医生团队或社区支持人员。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000009', '群里能不能问药', array['群里问药', '微信群问药', '群里能不能问', '健康小组'], '健康小组', '群里适合问流程、提醒、小课堂和日常打卡问题；涉及停药、换药、药量调整或报告严重程度的专业问题，不适合在群里直接处理。', '普通流程问题可以继续问，专业判断建议联系家庭医生或线下医生。', true, 'medium', true),
  ('90000000-0000-4000-8000-000000000010', '积分可以提现吗', array['积分提现', '可以提现吗', '积分能不能换钱'], '任务积分', '积分不能提现，不能充值，不能购买处方药，也不能医保支付。积分主要用于鼓励完成健康任务。', '您可以继续完成打卡任务或查看当前可兑换项目。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000011', '保健品能买吗', array['保健品', '能买吗', '药茶', '养生产品'], '防诈骗提醒', '购买保健品要谨慎。保健品不能替代正规治疗，也不能替代处方药。遇到夸大疗效或让您停药的宣传要特别小心。', '拿不准时，建议先问家庭医生或家属。', true, 'medium', true),
  ('90000000-0000-4000-8000-000000000012', '家庭医生是不是私人医生', array['私人医生', '家庭医生是不是私人医生', '随叫随到'], '签约服务', '家庭医生不是私人医生，主要负责基本医疗、慢病管理、健康咨询、随访和转诊协助，不等于随叫随到。', '可以先了解自己的签约团队和可提供服务范围。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000013', '什么问题应该找家庭医生', array['什么问题找家庭医生', '找家庭医生', '找家医'], '联系医生', '慢病随访、配药规则、体检报告初步解释、健康管理和转诊路径这类问题，适合先联系家庭医生团队。', '可以把您的问题说清楚：是什么问题、持续多久、有没有明显不适。', true, 'medium', true),
  ('90000000-0000-4000-8000-000000000014', '什么情况应该直接去医院', array['直接去医院', '什么情况去医院', '急诊', '严重'], '紧急就医', '如果出现胸痛、呼吸困难、意识异常、严重低血糖、肢体无力、言语不清等情况，不建议只在线上等待回复，应立即就医。', '出现紧急风险时，请优先线下就医或拨打急救电话。', true, 'emergency', true),
  ('90000000-0000-4000-8000-000000000015', '我能不能停药', array['停药', '能不能停药', '不吃药'], '安全边界', '是否停药需要医生结合个人病情、检查结果和用药情况判断。家医 Claw 不能建议停药。', '请不要自行停药，建议尽快联系家庭医生或线下医生。', true, 'high', true),
  ('90000000-0000-4000-8000-000000000016', '胸痛怎么办', array['胸痛', '胸闷', '胸口疼'], '紧急就医', '胸痛可能有风险，尤其是伴随呼吸困难、出汗、头晕、恶心时，应立即就医。家医 Claw 不能替代急诊判断。', '不要在线上等待，建议立刻线下就医或拨打急救电话。', true, 'emergency', true),
  ('90000000-0000-4000-8000-000000000017', '家庭医生签约后能得到什么服务', array['签约', '家庭医生服务', '能得到什么服务'], '签约服务', '签约后通常可获得健康咨询、慢病随访、配药规则说明、体检相关服务和必要时的转诊协助。', '可以先确认自己的签约团队和联系方式。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000018', '老年体检报告在哪里拿', array['体检报告在哪里拿', '领报告', '老年体检'], '体检流程', '体检报告一般由社区卫生服务中心、服务站或家庭医生团队根据当地安排发放，有些地区支持线上查看。', '先看社区通知，不清楚时联系社区卫生服务中心。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000019', '体检发现异常怎么办', array['体检异常', '报告异常', '异常怎么办'], '体检报告', '体检异常后不要自己判断严重程度。不同指标的意义不同，通常需要医生结合完整报告和症状判断。', '建议尽快联系家庭医生或线下医生进一步确认。', true, 'medium', true),
  ('90000000-0000-4000-8000-000000000020', '长处方是什么意思', array['长处方', '长期处方', '一次开多久'], '配药用药', '长处方通常指病情相对稳定、需要长期用药的居民，在符合规定时一次开具较长周期药量的处方。', '可以咨询家庭医生自己是否符合长处方条件。', true, 'low', true),
  ('90000000-0000-4000-8000-000000000021', '延伸处方是什么意思', array['延伸处方', '上级医院药', '社区续配'], '配药用药', '延伸处方一般是把上级医院的部分慢病常用药，通过规定流程延伸到社区继续配药。', '可以带上旧处方或药盒，咨询家庭医生团队。', true, 'low', true),
  ('90000000-0000-4000-8000-000000000022', '配药遇到药品不全怎么办', array['药品不全', '配不到药', '社区没药'], '配药用药', '社区药品目录和上级医院可能不完全一致，遇到配不到的药时，不建议自己随便换药。', '建议带药盒或旧处方联系家庭医生，由医生判断下一步。', true, 'medium', true),
  ('90000000-0000-4000-8000-000000000023', '糖尿病患者为什么不能随便断药', array['糖尿病', '断药', '停药', '降糖药'], '慢病科普', '糖尿病需要长期管理，随便断药可能导致血糖波动并增加并发症风险。', '请不要自行停药，如有不适应尽快联系医生。', true, 'high', true),
  ('90000000-0000-4000-8000-000000000024', '高血压患者多久随访一次', array['高血压随访', '多久随访', '血压随访'], '慢病随访', '高血压患者通常需要定期随访，具体频率会根据控制情况和当地服务规范安排。', '可以联系家庭医生确认自己的随访安排。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000025', '糖尿病患者多久随访一次', array['糖尿病随访', '血糖随访', '多久随访'], '慢病随访', '糖尿病患者通常需要定期随访，内容包括血糖、用药、生活方式和并发症风险。', '建议保留近期血糖记录，随访时提供给医生参考。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000026', '转诊专家号怎么预约', array['转诊', '专家号', '预约专家', '上级医院'], '转诊预约', '是否需要转诊和如何预约专家号，一般需要家庭医生先根据病情和规则判断。', '建议先联系家庭医生团队说明情况。', true, 'medium', true),
  ('90000000-0000-4000-8000-000000000027', '家庭医生能不能上门', array['上门', '上门服务', '家庭医生上门'], '服务边界', '家庭医生是否可以上门，要看当地服务规定、居民情况和医疗安全要求，并不是所有问题都适合上门处理。', '如有行动困难或特殊情况，可先联系家庭医生团队说明。', true, 'medium', true),
  ('90000000-0000-4000-8000-000000000028', '非工作时间能不能联系家庭医生', array['非工作时间', '晚上', '周末', '节假日'], '服务边界', '家庭医生不是 24 小时私人医生。普通问题建议在工作时间联系；如遇急症风险，应立即线下就医。', '普通流程问题可以先问 Claw，紧急问题不要在线上等待。', false, 'medium', true),
  ('90000000-0000-4000-8000-000000000029', '哪些问题不能由家医Claw回答', array['不能回答', '哪些不能问', '诊断', '处方', '停药'], '安全边界', '家医 Claw 不能提供诊断、处方、停药、换药、剂量调整和报告严重程度判断。', '遇到专业医疗判断问题，请联系家庭医生或线下就医。', true, 'high', true),
  ('90000000-0000-4000-8000-000000000030', '老人不会用手机怎么办', array['不会用手机', '老人不会操作', '智能手机'], '适老帮助', '不会用手机时，可以请家属、居委、楼组长或社区工作人员协助，尽量减少复杂操作。', '可以把常用联系人放到一键找人里，方便直接求助。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000031', '居委会能帮忙做什么', array['居委会', '楼组长', '社区', '卫生干部'], '社区支持', '居委会和社区工作人员通常可以协助通知体检、帮忙登记、提醒活动时间、协助老人找到服务入口。', '流程和通知类问题可以先问社区支持人员。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000032', '哪些症状需要立刻就医', array['立刻就医', '急症', '危险症状', '120'], '紧急就医', '出现胸痛、呼吸困难、意识异常、严重低血糖、肢体无力、言语不清等情况时，应立刻就医。', '不要只在线上等待，先线下就医。', true, 'emergency', true),
  ('90000000-0000-4000-8000-000000000033', '血压很高怎么办', array['血压很高', '血压高', '高血压怎么办'], '慢病科普', '血压明显升高时，不建议自行加药或停药。可以先安静休息后复测，并记录数值和身体感受。', '如伴随胸痛、头晕明显、呼吸困难等情况，应立即就医。', true, 'high', true),
  ('90000000-0000-4000-8000-000000000034', '血糖很低怎么办', array['血糖低', '低血糖', '手抖', '出汗'], '慢病科普', '低血糖可能带来风险，尤其是出现出汗、心慌、手抖、意识不清时，应尽快处理并及时就医。', '如有意识异常或明显不适，请立刻线下就医。', true, 'emergency', true),
  ('90000000-0000-4000-8000-000000000035', '看完小课堂有什么用', array['小课堂', '课程', '科普', '有什么用'], '家医小课堂', '家医小课堂主要帮助居民理解慢病管理、体检、用药注意事项和防诈骗知识。', '可以先从高血压、糖尿病、体检报告相关课程开始看。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000036', '我想让Claw帮我整理问题给医生', array['整理问题', '帮我说明', '转给医生', '摘要'], '联系医生', '可以。Claw 可以帮您把问题整理成简短说明，方便您联系家庭医生团队，但不能代替医生判断。', '您可以先把问题、持续时间和是否有不适告诉我。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000037', '我在群里发血压可以吗', array['群里发血压', '血压打卡', '群打卡'], '健康小组', '可以在健康小组里做日常打卡，但这些记录只用于日常健康管理参考，不能代替医生判断。', '发记录时可以写清时间、数值和是否有不适。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000038', '家庭医生团队里除了医生还有谁', array['家庭医生团队', '护士', '药师', '公卫'], '家庭医生团队', '家庭医生团队通常不只有医生，还可能包括护士、公卫人员、药师和社区支持人员。', '普通流程问题不一定都要直接找医生。', false, 'low', true),
  ('90000000-0000-4000-8000-000000000039', '药量能不能自己加减', array['药量', '剂量', '加药', '减药'], '安全边界', '药物剂量不能自己调整。不同药有不同风险，随意加减可能带来危险。', '请带上用药清单和近期记录，联系家庭医生或线下医生判断。', true, 'high', true),
  ('90000000-0000-4000-8000-000000000040', '今天忘记吃药怎么办', array['忘记吃药', '漏服', '忘吃药'], '配药用药', '漏服后是否需要补服，取决于药物种类和时间间隔。家医 Claw 不能提供具体补服建议。', '建议查看原药品说明，或联系家庭医生、药师咨询。', true, 'medium', true)
on conflict (id) do update
set
  question = excluded.question,
  keywords = excluded.keywords,
  category = excluded.category,
  answer = excluded.answer,
  next_step = excluded.next_step,
  suggest_doctor = excluded.suggest_doctor,
  risk_level = excluded.risk_level,
  is_active = excluded.is_active;
